insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '37168e7c-dc9e-4879-a5cd-d615fd0a0f04', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'bac7288f-06d8-4765-b6d3-34f8fad2506f', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['You''re right.', 'Let''s have lunch.', 'Fruit is good.'],
  'Cuando alguien te da un consejo, la respuesta natural en inglés es aceptarlo o rechazarlo, no cambiar de tema.', 'publicada', 'modelo', '077ccd1a605bec9ecc451420d3bed274';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('37168e7c-dc9e-4879-a5cd-d615fd0a0f04', 0, 'La frase es un consejo, y lo que se espera es aceptarlo: darle la razón a quien lo da. Proponer almorzar cambia de tema, y comentar que la fruta es buena no responde a lo que dijo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6ebbc3e1-fcad-435f-9312-5f2dc8256a54', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'a7337b9e-11e0-4732-a3ca-6b4928b2302d', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['I need a break.', 'Not everyone practices.', 'Most weekends.'],
  'Fíjate en la palabra que abre la pregunta: how often pide frecuencia, how long pide duración, how much pide cantidad.', 'publicada', 'modelo', '2d0ce29f6fdb5544529aded7b64544f6';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6ebbc3e1-fcad-435f-9312-5f2dc8256a54', 2, '«How often» pregunta por la frecuencia, así que la respuesta tiene que decir cada cuánto: casi todos los fines de semana. Las otras dos hablan de descanso y de otras personas, no de con qué frecuencia baila.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '169d26e2-4608-46ad-95fb-b8b99ab8fb8d', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '1467b38c-30aa-4baf-9991-f5dea93f9935', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['I ordered pizza.', 'It''s still not working.', 'The waiter was late.'],
  'Una respuesta puede contradecir lo que acaban de decir: no busques siempre la que esté de acuerdo.', 'publicada', 'modelo', '5f99347986690d8a9fe932d988c9d43a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('169d26e2-4608-46ad-95fb-b8b99ab8fb8d', 1, 'Quien responde contradice la noticia: dice que el horno sigue sin servir. Es la única de las tres que se refiere al horno; las otras hablan de pizza y de un mesero, que no vienen al caso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '66ec973f-6bd2-4171-9f39-11bd62657bae', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'e6d287ee-394e-4941-9eb7-a674c82554f9', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Answer!', 'Again?', 'Bye.'],
  'A una invitación se responde aceptando, rechazando o comentándola. Descarta lo que no haga ninguna de las tres.', 'publicada', 'modelo', '3c0201c9c3845b7190412bb8c43d243a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('66ec973f-6bd2-4171-9f39-11bd62657bae', 1, 'Ante una invitación repetida, «¿Otra vez?» es una reacción natural que la comenta sin aceptarla ni rechazarla del todo. Despedirse o dar una orden no responden a una propuesta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f5e9f508-eef3-4c66-8e4e-c137287c7cee', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '0849d0c4-1200-49e5-89aa-1d95f5ed69e7', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Not often.', 'That''s brilliant!', 'What''s wrong?'],
  'La expresión «I’m afraid…» avisa de que viene una mala noticia; la respuesta debería reconocerla.', 'publicada', 'modelo', 'ae42315872c69dcafe0efec65d18066c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f5e9f508-eef3-4c66-8e4e-c137287c7cee', 2, '«I’m afraid» anuncia algo que preocupa, así que lo natural es preguntar qué pasa con el computador que tiene. Celebrarlo choca con esa preocupación, y hablar de frecuencia no responde nada.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '55e0fff6-afcc-408b-a197-db019e23f3b2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '6f95845c-7e2c-4532-b878-d2e2f3ce33ab', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['A month ago.', 'Yes, I agree.', 'At the moment.'],
  'A una pregunta con «yet» se responde con lo que ya pasó y cuándo pasó.', 'publicada', 'modelo', '32df59a731d061f0764513580f02c5f0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('55e0fff6-afcc-408b-a197-db019e23f3b2', 0, 'La pregunta es si ya se inscribió, y la respuesta confirma que sí diciendo cuándo: hace un mes. Estar de acuerdo no responde a una pregunta de sí o no sobre un hecho.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '729f8da0-95c4-40e9-9fd9-a2aaecac2eb2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'cae78e85-2c10-45ef-abf2-b84221be99d6', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['It''s kind.', 'See you soon.', 'Of course!'],
  'A una instrucción se responde aceptándola («Of course», «Sure») o poniendo un reparo.', 'publicada', 'modelo', '865ab2db7beb5cc126f59be452121f2c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('729f8da0-95c4-40e9-9fd9-a2aaecac2eb2', 2, 'Es una instrucción, y lo natural es comprometerse a cumplirla. Despedirse deja la instrucción sin responder, y calificarla de amable no dice si se va a hacer.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'aaa3fa77-b674-4b3d-a951-93508dc09c84', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '369051fe-4deb-40e4-b9fe-a24c0ad7e3c6', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['I''ll do it myself.', 'I''ll go straight.', 'I''ll look for it.'],
  'Responde a la palabra interrogativa: who pide una persona, where un lugar, when un momento.', 'publicada', 'modelo', 'dfb71b16c0990c0911c964c3db5eeae8';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('aaa3fa77-b674-4b3d-a951-93508dc09c84', 0, 'La pregunta es QUIÉN va a hacerlo, y la respuesta nombra a la persona: yo mismo. Las otras dos dicen qué se va a hacer, no quién.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '28c8ae56-df64-4936-867e-8ea9c3a8cf9b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'edb45b72-6644-49b9-ace7-839836027257', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Good job!', 'Sure!', 'Me too.'],
  '«Would you like…?» es una invitación: se acepta o se rechaza.', 'publicada', 'modelo', '2ff7f56e76e8d4bab01701c82260e28b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('28c8ae56-df64-4936-867e-8ea9c3a8cf9b', 1, 'Es una invitación, y lo que corresponde es aceptarla. Felicitar supone un trabajo ya hecho, y «yo también» responde a una afirmación, no a una propuesta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '54123d33-cf07-45c5-937d-db73f1bb5d59', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '48dc256e-8928-46c6-972e-c01b6462b075', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['I feel fine!', 'So do I.', 'I''d like it!'],
  'Para decir «yo también» sobre una costumbre en presente, el inglés usa «So do I».', 'publicada', 'modelo', 'dfd03f3784a0c7caae87bd850601d590';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('54123d33-cf07-45c5-937d-db73f1bb5d59', 1, 'Quien responde cuenta que hace lo mismo. «So do I» es la fórmula del inglés para sumarse a una costumbre que el otro acaba de contar; las otras dos hablan de cómo se siente o de lo que le gustaría.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '8ec1ebb2-c267-4f61-a160-db91930cf70f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'ea7117d6-bb3f-4bf9-9524-742168a45835', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Let''s go there!', 'You''re welcome!', 'Yeah, why not?'],
  '«What about…?» propone un plan; la respuesta lo acepta o lo cambia.', 'publicada', 'modelo', '01d0a1490d6abfef069ab0c48d11207b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8ec1ebb2-c267-4f61-a160-db91930cf70f', 2, 'Es una propuesta de quedarse en casa, y se acepta con entusiasmo. Proponer ir a otro lado contradice el plan, y «de nada» responde a un agradecimiento que nadie hizo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '80add869-48d8-4f4d-8e3f-2773a7a4a149', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '998f95d6-7344-4857-8207-ac9bcc526fa6', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Ok, then.', 'Let him see.', 'You mustn''t go.'],
  'Cuando alguien rechaza algo, la respuesta natural es aceptar el rechazo.', 'publicada', 'modelo', '5e681549db776043e752d7e85870a6bd';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('80add869-48d8-4f4d-8e3f-2773a7a4a149', 0, 'La otra persona acepta la negativa sin insistir. Las demás hablan de un tercero o prohíben algo que nadie propuso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f26b84ee-c70d-4fde-ba56-04384bd9f6fb', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '60728710-b420-429c-af12-2efda73d14b7', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['I suppose so.', 'Never mind!', 'I travel tomorrow.'],
  'Ante una disculpa, el inglés responde quitándole importancia: «Never mind», «Don’t worry», «That’s OK».', 'publicada', 'modelo', 'bf8010e45351d0dfe4e85c431ea0004a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f26b84ee-c70d-4fde-ba56-04384bd9f6fb', 1, 'Es una disculpa, y «no importa» le quita peso: es lo que se dice para tranquilizar a quien se excusa. Suponer que sí no encaja con una disculpa, y anunciar un viaje cambia de tema.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'fb6c9517-f583-436a-94a5-9b2754e669fc', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd9aacb2-efea-4ad1-898a-c1001b6d418e', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Who is it?', 'How far?', 'Do you?'],
  'Las preguntas cortas de eco —«Do you?», «Did he?», «Is it?»— sirven para mostrar interés, no para pedir información.', 'publicada', 'modelo', 'cd7fcad7e7e422c7523f7984211ca499';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fb6c9517-f583-436a-94a5-9b2754e669fc', 2, '«Do you?» es la coletilla con la que el inglés muestra interés por lo que el otro acaba de opinar, sin estar de acuerdo ni en desacuerdo. Preguntar quién es o qué tan lejos queda no viene al caso: ya se sabe de quién se habla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e51f73bb-84d6-42fa-9230-873d09a46c04', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '08b70a81-9f8d-4f7c-96da-363a76096ca1', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Yes, I know.', 'That''s a good idea.', 'I''ve got one, thanks.'],
  '«Why don’t we…?» no es un reproche: es la forma de proponer un plan.', 'publicada', 'modelo', '1abc0df01c60b493bf88c129b3294c35';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e51f73bb-84d6-42fa-9230-873d09a46c04', 1, 'Es una propuesta de plan y se acepta llamándola buena idea. «Ya lo sé» respondería a un dato, y «ya tengo uno» a un ofrecimiento de objeto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '56647cb1-86ab-4775-8e9b-a980aaf8dcab', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '985fba1c-8422-48cb-8d32-a51ff7ee485d', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['No thanks.', 'No problem.', 'No, it hasn''t.'],
  'Las tres opciones empiezan igual: lo que decide es qué sigue después del «no».', 'publicada', 'modelo', 'e314f213b5f12607bc4f44d264797f22';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('56647cb1-86ab-4775-8e9b-a980aaf8dcab', 1, 'Es un agradecimiento, y «no problem» es la fórmula habitual para restarle importancia. «No thanks» rechaza algo que ofrecen, y la tercera responde a una pregunta que nadie hizo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6f6fbe15-d338-4785-a3e1-a80006e6155f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'e1b4b031-1aa6-4209-90ab-75a60f5350e2', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['How are you?', 'Why can''t you?', 'When did he call?'],
  'Una petición se puede aceptar o discutir; preguntar «¿y por qué tú no?» es discutirla.', 'publicada', 'modelo', 'c1c19a44693d966dee279da746c848c7';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6f6fbe15-d338-4785-a3e1-a80006e6155f', 1, 'Ante una orden, quien responde se resiste preguntando por qué no la hace quien la pide. Saludar ignora la petición, y preguntar cuándo llamó supone una llamada pasada, no el teléfono que suena ahora.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '8ae4c5ef-5eaf-46b2-9893-bfec916f0e66', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '1dbf3199-fe60-4574-bbb2-852902735929', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['If you really want it.', 'It''s all right now.', 'That''s nice of you.'],
  'A un ofrecimiento espontáneo se responde agradeciendo: «That’s nice of you», «Thank you».', 'publicada', 'modelo', 'efafd47db87991c38f523f071958bb3a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8ae4c5ef-5eaf-46b2-9893-bfec916f0e66', 2, 'Es un ofrecimiento de lavar los platos, y se agradece reconociendo el gesto. Las otras dos suenan a permiso concedido a regañadientes o a que el asunto ya se resolvió, y ninguna agradece.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '7990fd98-a634-4804-8c29-04438c969caf', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '219f7c5a-e52f-49c8-97f9-2a86eda4ae68', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['That''s quick!', 'Of course.', 'May I keep this?'],
  '«Can you…?» pide un favor; la respuesta lo concede o lo niega.', 'publicada', 'modelo', '7b8b1b80aca6df3d56c12cf3cbff4933';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7990fd98-a634-4804-8c29-04438c969caf', 1, 'Es una petición de favor y se acepta. Comentar la rapidez no responde nada, y pedir quedarse con algo cambia el sentido: le están pidiendo sostener la cámara, no regalándosela.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '848d0f73-9c87-4416-8c2d-6b757e706652', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'd589d15e-0c7e-4e40-a71b-614291c6dd05', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Be careful!', 'That''s great!', 'As soon as possible!'],
  'A una noticia se reacciona valorándola: «That’s great», «Oh no», «Really?».', 'publicada', 'modelo', '04e92f2490e1b17bf54b4537f8140d2b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('848d0f73-9c87-4416-8c2d-6b757e706652', 1, 'Es una noticia y se recibe con entusiasmo. Advertir que tenga cuidado no viene a cuento con una invitación, y «lo antes posible» respondería a una pregunta sobre cuándo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c365bd9c-429e-4ee6-ad29-07ffc39ab91f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'b5aaada9-84be-4280-91c0-67dcc04b569f', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['You''re lucky!', 'Very kind of you!', 'Just amazing!'],
  'Una pregunta negativa como «Wasn’t it…?» busca que le den la razón, no información.', 'publicada', 'modelo', 'cb78f5e89bcb90c0cf6702f964f75276';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c365bd9c-429e-4ee6-ad29-07ffc39ab91f', 2, 'Quien pregunta ya está diciendo que el viaje fue maravilloso y busca que se lo confirmen: la respuesta lo confirma con más entusiasmo todavía. Las otras dos felicitan o agradecen a la persona, no opinan del viaje.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '29677d21-1cb6-4ae1-a2d9-b1daeae78983', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '664bd8eb-5dd3-4d4a-a6cd-d533792e5d72', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['That''s terrible!', 'Never again.', 'How long is it?'],
  'Primero decide si la noticia es buena o mala: eso descarta la mitad de las opciones.', 'publicada', 'modelo', 'c1b2fe2cf07424e5122d7554ee09f1c6';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('29677d21-1cb6-4ae1-a2d9-b1daeae78983', 0, 'Es una mala noticia y se reacciona lamentándola. «Nunca más» supone algo que se decidió no repetir, y preguntar la duración no encaja con haber perdido el tren.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4ee0894a-b4f3-458f-90b9-6187938612a7', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '7df8fd10-0e4f-4b5c-b9d6-69893eda5057', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['How often?', 'That''s exciting!', 'What happened?'],
  'Cuando la frase deja algo sin explicar, la mejor respuesta suele ser pedir esa explicación.', 'publicada', 'modelo', 'e02af02e5389662e94e8ba20929610c9';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4ee0894a-b4f3-458f-90b9-6187938612a7', 2, 'Quien responde pide la explicación de por qué no pudieron nadar, que es lo que la frase deja pendiente. Celebrarlo choca con una contrariedad, y preguntar la frecuencia no responde al hecho puntual de ayer.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'a6d0bd35-8eb4-4f11-bb73-0a72005aa8b0', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'fee288ff-3262-4c98-808c-dc4d4b365c6b', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Did you?', 'Was it?', 'Why not?'],
  'La pregunta de eco copia el verbo de la frase: «I loved…» pide «Did you?»; «It was…» pide «Was it?».', 'publicada', 'modelo', '8a001ff97cf67f5da64f9747a9ffa739';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a6d0bd35-8eb4-4f11-bb73-0a72005aa8b0', 0, 'La frase está en pasado y el verbo es «loved», así que la pregunta de eco tiene que repetir ese verbo: «Did you?». «Was it?» respondería a una frase con el verbo to be, y «Why not?» a una negación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '5842b200-1a54-4fa7-986b-af3be4b243c1', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '71475496-1ad9-4ba0-bfd1-ceec986337d3', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['What size?', 'Just a small bit.', 'Never mind!'],
  'En una tienda, la respuesta suele pedir el dato que falta para atender: talla, color, cantidad.', 'publicada', 'modelo', '047dc919cd090c40a5520df01419f45c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5842b200-1a54-4fa7-986b-af3be4b243c1', 0, 'Quien atiende concede la prueba y pide el dato que le falta: la talla. Las otras dos hablan de cantidad o quitan importancia a algo, y ninguna de las dos tiene sentido ante quien quiere medirse un vestido.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'a4860ba7-ecf4-478d-9415-d79973db235f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '4a595464-4000-4f77-950a-f7b9e9805957', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Be careful!', 'That''s easy!', 'Oh, I can move!'],
  'Cuando te señalan un error tuyo, la respuesta esperada es corregirlo, no comentarlo.', 'publicada', 'modelo', 'e3c36f3eed8b97c5d50aedab1e352008';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a4860ba7-ecf4-478d-9415-d79973db235f', 2, 'Le están reclamando el puesto con cortesía, y lo que corresponde es ofrecerse a cambiarse. Advertir que tenga cuidado o decir que es fácil no resuelven el reclamo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '28b08cbc-90d9-442b-ac65-ad6c837c5c99', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3162912-454e-45ed-a76e-c8b8856bb7a9', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['You must practice!', 'Will it take long?', 'It doesn''t matter.'],
  'No toda respuesta a una petición es sí o no: preguntar por las condiciones también la responde.', 'publicada', 'modelo', '31a21d9f2f20a21d54b61ebf22d9bc7d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('28b08cbc-90d9-442b-ac65-ad6c837c5c99', 1, 'Antes de aceptar el favor, quien responde pregunta cuánto tiempo le va a tomar: es una respuesta que sigue la conversación. Mandarlo a practicar no ayuda, y «no importa» respondería a una disculpa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e90a55f2-1a79-4ca2-a1ce-36a478753c86', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-3-dialogos'),
  (select id from public.lotes where codigo = '2026-B'),
  '8b42c86c-9ecc-4e77-82d1-551f63037f5b', 'Parte 3 · Diálogos cortos',
  'Choose the best reply.',
  array['Don''t change it!', 'Let''s look for it.', 'How about cooking?'],
  'A una queja se responde resolviéndola: si alguien se aburre, se le propone un plan.', 'publicada', 'modelo', '0cea9a803b8f7f8615c2b5f556899c95';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e90a55f2-1a79-4ca2-a1ce-36a478753c86', 2, 'Ante la queja de aburrimiento, la respuesta propone otra cosa que hacer. Pedirle que no cambie nada va en contra de la queja, y buscar algo supone un objeto perdido que nadie mencionó.');

